                 void (*fn)(const char *key, void *value, void *ctx),
                 void *ctx)
 {
-    (void)t;
-    (void)fn;
-    (void)ctx;                  /* M1 */
+    foreach_subtree(t->root, fn, ctx);
 }

 /* In-order walk of one subtree, checking every rule at once.

