 97	/* Free one node: the value (only if the tree owns values), the key copy, and
 98	 * the struct. Does not touch left/right/parent -- unlinking is the caller's
 99	 * job, and this must never be called on a node still reachable from the tree. */
100	static void node_release(const rbtree_t *t, struct rbnode *n)
101	{
102	    if (t->value_free != NULL) {
103	        t->value_free(n->value);
104	    }
105	    rb_free(n->key);
106	    rb_free(n);
107	}
