269	int rb_insert(rbtree_t *t, const char *key, void *value)
270	{
271	    struct rbnode *parent = NULL;
272	    struct rbnode *cur = t->root;
273	    int cmp = 0;
274	
275	    /* Invariant: key is not in any node above cur, and if it is in the tree
276	     * at all it is somewhere in the subtree rooted at cur. */
277	    while (cur != NULL) {
278	        cmp = strcmp(key, cur->key);
279	        if (cmp == 0) {
280	            /* Key already present: replace the value. The tree is the old
281	             * value's only owner, so free it first (if we own values).
282	             * Unless the caller handed back the very pointer we already
283	             * hold -- then there is nothing old to free, and freeing it
284	             * would leave cur->value dangling for rb_destroy to free again. */
285	            if (t->value_free != NULL && cur->value != value) {
286	                t->value_free(cur->value);
287	            }
288	            cur->value = value;
289	            return 0;                       /* count unchanged */
290	        }
291	        parent = cur;
292	        cur = (cmp < 0) ? cur->left : cur->right;
293	    }
294	
295	    /* Fell off the tree: cur is NULL and parent is the node to hang from.
296	     * cmp still holds the comparison against parent, so it tells us which side. */
297	    struct rbnode *n = node_alloc(key, value);
298	    if (n == NULL) {
299	        return -1;                          /* tree unchanged; caller keeps value */
300	    }
301	    n->parent = parent;
302	
303	    if (parent == NULL) {
304	        t->root = n;                        /* first node in an empty tree */
305	    } else if (cmp < 0) {
306	        parent->left = n;
307	    } else {
308	        parent->right = n;
309	    }
310	    t->count++;
311	
312	    insert_fixup(t, n);
