331	/* ------------------------------------------------------------------------
332	 * Deletion. Kept apart from the insert machinery so a failing delete test
333	 * points at exactly these functions. Nothing here allocates: the header
334	 * gives rb_delete no way to report an allocation failure, so it must never
335	 * need one. No recursion either: delete and its fixup are loops.
336	 * --------------------------------------------------------------------- */
337	
338	/* Leftmost node under n: the smallest key in that subtree. Precondition: n
339	 * is not NULL. Used to find the in-order successor of a node with two
340	 * children (the minimum of its right subtree). */
341	static struct rbnode *tree_minimum(struct rbnode *n)
342	{
343	    /* Invariant: the smallest key of the original subtree is at or below n. */
344	    while (n->left != NULL) {
345	        n = n->left;
346	    }
347	    return n;
348	}
349	
350	/* Make u's parent point at v instead of u. v may be NULL. Updates t->root
351	 * when u was the root. Does not touch u's own pointers, and cannot set
352	 * v->parent when v is NULL -- which is why delete_fixup is handed the
353	 * parent separately. */
354	static void transplant(rbtree_t *t, struct rbnode *u, struct rbnode *v)
355	{
356	    if (u->parent == NULL) {
357	        t->root = v;
358	    } else if (u == u->parent->left) {
359	        u->parent->left = v;
360	    } else {
361	        u->parent->right = v;
362	    }
363	    if (v != NULL) {
364	        v->parent = u->parent;
365	    }
366	}
367	
368	/* Pay off the "doubly black" debt left behind by unlinking a black node.
369	 *
370	 * x is whatever took the unlinked node's place -- possibly NULL, since a
371	 * missing child counts as black -- and x_parent is its parent. Every path
372	 * through x is now one black short of every other path. The loop climbs
373	 * toward the root until the debt is paid, in one of three ways: a red node
374	 * absorbs it by turning black, a rotation drags a red node across from the
375	 * sibling's side, or the debt reaches the root and simply dissolves (every
376	 * path lost the same one black, so they are all still equal).
377	 *
378	 * Loop invariant: x is doubly black; every other rule holds. The sibling w
379	 * is never NULL: before the delete both of x_parent's sides had the same
380	 * black-height, and a black node came off x's side, so the sibling's side
381	 * still has black-height >= 2 -- which takes at least one real node. That
382	 * is also why, when x is NULL, "x == x_parent->left" still picks the right
383	 * side: only the emptied side can be NULL.
384	 *
385	 * Termination: case 2 climbs one level per pass, so at most height passes.
386	 * Case 1 always drops into 2, 3 or 4 with a black sibling; if it is 2, the
387	 * new x is the parent we just painted red, so the next test exits. Cases
388	 * 3->4 and 4 end the loop directly. At most three rotations in total. */
389	static void delete_fixup(rbtree_t *t, struct rbnode *x, struct rbnode *x_parent)
390	{
391	    while (x != t->root && !is_red(x)) {
392	        if (x == x_parent->left) {
393	            struct rbnode *w = x_parent->right;     /* sibling; never NULL */
394	
395	            if (is_red(w)) {
396	                /* Case 1: red sibling. Not a shape we can fix directly, so
397	                 * rotate to give x a black sibling, then fall through. */
398	                w->color = RB_BLACK;
399	                x_parent->color = RB_RED;
400	                rotate_left(t, x_parent);
401	                w = x_parent->right;                /* new sibling, black */
402	            }
403	
404	            if (!is_red(w->left) && !is_red(w->right)) {
405	                /* Case 2: black sibling, no red child. Take one black off
406	                 * the sibling's side as well (paint w red): now both sides
407	                 * are short by one, so the debt moves up to the parent. */
408	                w->color = RB_RED;
409	                x = x_parent;
410	                x_parent = x->parent;
411	            } else {
412	                if (!is_red(w->right)) {
413	                    /* Case 3: the red child is on the near side. Rotate at
414	                     * w to move it to the far side, then fall into case 4. */
415	                    w->left->color = RB_BLACK;
416	                    w->color = RB_RED;
417	                    rotate_right(t, w);
418	                    w = x_parent->right;
419	                }
420	                /* Case 4: red child on the far side. Rotate at the parent
421	                 * so w moves up and the red child comes across to x's side;
422	                 * the recoloring restores every path's black count. Paid. */
423	                w->color = x_parent->color;
424	                x_parent->color = RB_BLACK;
425	                w->right->color = RB_BLACK;
426	                rotate_left(t, x_parent);
427	                x = t->root;                        /* done: ends the loop */
428	                x_parent = NULL;
429	            }
430	        } else {
431	            /* Mirror of the block above: every left and right swapped. */
432	            struct rbnode *w = x_parent->left;
433	
434	            if (is_red(w)) {
435	                w->color = RB_BLACK;
436	                x_parent->color = RB_RED;
437	                rotate_right(t, x_parent);
438	                w = x_parent->left;
439	            }
440	
441	            if (!is_red(w->right) && !is_red(w->left)) {
442	                w->color = RB_RED;
443	                x = x_parent;
444	                x_parent = x->parent;
445	            } else {
446	                if (!is_red(w->left)) {
447	                    w->right->color = RB_BLACK;
448	                    w->color = RB_RED;
449	                    rotate_left(t, w);
450	                    w = x_parent->left;
451	                }
452	                w->color = x_parent->color;
453	                x_parent->color = RB_BLACK;
454	                w->left->color = RB_BLACK;
455	                rotate_right(t, x_parent);
456	                x = t->root;
457	                x_parent = NULL;
458	            }
459	        }
460	    }
461	
462	    if (x != NULL) {
463	        x->color = RB_BLACK;    /* a red x absorbs the debt; the root stays black */
464	    }
465	}
