467	int rb_delete(rbtree_t *t, const char *key)
468	{
469	    struct rbnode *z = t->root;
470	
471	    /* Invariant: if key is in the tree, it is in the subtree rooted at z. */
472	    while (z != NULL) {
473	        int cmp = strcmp(key, z->key);
474	        if (cmp == 0) {
475	            break;
476	        }
477	        z = (cmp < 0) ? z->left : z->right;
478	    }
479	    if (z == NULL) {
480	        return -1;                          /* absent: nothing touched */
481	    }
482	
483	    if (z->left != NULL && z->right != NULL) {
484	        /* Two children: hoist. The in-order successor y is the smallest key
485	         * to z's right, so it has no left child. Swap the payloads: z's slot
486	         * now holds y's key/value (still in order), and y's node holds the
487	         * doomed key/value. Then delete y's node instead. Colors stay put --
488	         * the tree's shape and coloring are untouched, only the payload
489	         * moved -- and each key and value still has exactly one owner. */
490	        struct rbnode *y = tree_minimum(z->right);
491	        char *k = z->key;
492	        void *v = z->value;
493	        z->key = y->key;
494	        z->value = y->value;
495	        y->key = k;
496	        y->value = v;
497	        z = y;
498	    }
499	
500	    /* z has at most one child. Splice z out: x takes its place. */
501	    struct rbnode *x = (z->left != NULL) ? z->left : z->right;  /* may be NULL */
502	    struct rbnode *x_parent = z->parent;
503	    bool z_was_black = (z->color == RB_BLACK);  /* read before z is freed */
504	
505	    transplant(t, z, x);
506	    node_release(t, z);                     /* unlinked: nothing points at z now */
507	    t->count--;
508	
509	    if (z_was_black) {
510	        /* Unlinking a black node left every path through x one black short.
511	         * Unlinking a red one cost nothing. z is already gone, and x and
512	         * x_parent are never z, so the fixup cannot touch freed memory. */
513	        delete_fixup(t, x, x_parent);
514	    }
515	    return 0;
516	}
517	
518	size_t rb_size(const rbtree_t *t)
519	{
520	    return (t == NULL) ? 0 : t->count;
521	}
522	
523	/* In-order walk of one subtree: everything smaller, then this node, then
524	 * everything larger. Recursion is allowed here for this assignment (HW2
525	 * takes it away). The callback must not insert into or delete from the
526	 * tree it is walking -- the walk holds pointers into it. */
527	static void foreach_subtree(const struct rbnode *n,
528	                            void (*fn)(const char *key, void *value, void *ctx),
529	                            void *ctx)
530	{
531	    if (n == NULL) {
532	        return;
533	    }
534	    foreach_subtree(n->left, fn, ctx);
535	    fn(n->key, n->value, ctx);
536	    foreach_subtree(n->right, fn, ctx);
537	}
538	
539	void rb_foreach(const rbtree_t *t,
540	                void (*fn)(const char *key, void *value, void *ctx),
541	                void *ctx)
542	{
543	    foreach_subtree(t->root, fn, ctx);
544	}
545	
546	/* In-order walk of one subtree, checking every rule at once.
547	 *
548	 * The error travels in the RETURN VALUE; the data travels in the pointer
549	 * parameters. *prev is the last key seen (NULL before the first); every key
550	 * must be strictly greater. *count accumulates the real node count.
551	 * *black_height receives this subtree's black-height, but only on success.
552	 *
553	 * Every recursive call is followed by an early return if it failed, so the
554	 * first broken rule found -- however deep -- comes straight back up untouched. */
555	static int validate_subtree(const struct rbnode *n, const char **prev,
556	                            size_t *count, size_t *black_height)
557	{
558	    if (n == NULL) {
559	        *black_height = 1;                  /* the invisible black leaf */
560	        return RB_OK;
561	    }
562	
563	    /* Checks on this node first, before descending. */
564	    if (n->left != NULL && n->left->parent != n) {
565	        return RB_BAD_PARENT;
566	    }
567	    if (n->right != NULL && n->right->parent != n) {
568	        return RB_BAD_PARENT;
569	    }
570	    if (n->color == RB_RED && (is_red(n->left) || is_red(n->right))) {
571	        return RB_BAD_RED_RED;
572	    }
573	
574	    size_t left_bh = 0;
575	    int rc = validate_subtree(n->left, prev, count, &left_bh);
576	    if (rc != RB_OK) {
577	        return rc;                          /* early abort */
578	    }
579	
580	    if (*prev != NULL && strcmp(*prev, n->key) >= 0) {
581	        return RB_BAD_ORDER;
582	    }
583	    *prev = n->key;
584	    (*count)++;
585	
586	    size_t right_bh = 0;
587	    rc = validate_subtree(n->right, prev, count, &right_bh);
588	    if (rc != RB_OK) {
589	        return rc;                          /* early abort */
590	    }
591	
592	    /* Only compare once BOTH sides came back clean. */
593	    if (left_bh != right_bh) {
594	        return RB_BAD_BLACK_HEIGHT;
595	    }
596	
597	    *black_height = left_bh + (n->color == RB_BLACK ? 1 : 0);
598	    return RB_OK;
599	}
600	
601	int rb_validate(const rbtree_t *t)
602	{
603	    if (t->root != NULL) {
604	        if (t->root->parent != NULL) {
605	            return RB_BAD_ROOT_PARENT;
606	        }
607	        if (t->root->color != RB_BLACK) {
608	            return RB_BAD_ROOT_COLOR;
609	        }
610	    }
611	
612	    const char *prev = NULL;
613	    size_t count = 0;
614	    size_t black_height = 0;                /* received, not compared: every
615	                                               path below already agreed */
616	    int rc = validate_subtree(t->root, &prev, &count, &black_height);
617	    if (rc != RB_OK) {
618	        return rc;
619	    }
620	    if (count != t->count) {
621	        return RB_BAD_COUNT;
622	    }
623	    return RB_OK;
624	}
625	
626	/* Free a whole subtree, children before parent, so no freed node is ever
627	 * read again. Recursion is allowed in this assignment (HW2 takes it away). */
628	static void destroy_subtree(const rbtree_t *t, struct rbnode *n)
629	{
630	    if (n == NULL) {
631	        return;
632	    }
633	    destroy_subtree(t, n->left);
634	    destroy_subtree(t, n->right);
635	    node_release(t, n);
636	}
637	
638	void rb_destroy(rbtree_t *t)
639	{
640	    if (t == NULL) {
641	        return;                 /* the header promises NULL-safety */
642	    }
643	    destroy_subtree(t, t->root);
644	    rb_free(t);
645	}

