   148	+ * inserts b, a, c, d and "da" deletes d, then a. The full set of checks runs
   149	+ * after EVERY delete, so a two-step row (drop a red leaf to reach a shape,
   150	+ * then hit the case) and a drain (delete everything) are the same code path
   151	+ * as a one-delete row. */
   152	+struct del_case {
   153	+    const char *name;
   154	+    const char *insert;
   155	+    const char *victims;
   156	+};
   157	+
   158	+static bool deleted_before(const char *victims, size_t upto, char key)
   159	+{
   160	+    for (size_t j = 0; j < upto; j++) {
   161	+        if (victims[j] == key) {
   162	+            return true;
   163	+        }
   164	+    }
   165	+    return false;
