   171	+static rbtree_t *build_owned(const struct del_case *c, int *vals[])
   172	+{
   173	+    size_t n = strlen(c->insert);
   174	+    if (n > MAX_CASE_KEYS) {
   175	+        fprintf(stderr, "%s: %zu keys, harness holds %d\n", c->name, n, MAX_CASE_KEYS);
