    10	/* Invoked as: ./build/fuzz <op-count> [seed]
    11	 *
    12	 * Random inserts, finds and deletes against a reference model, with
    13	 * rb_validate and a full in-order comparison every VALIDATE_EVERY ops.
    14	 *
    15	 * The model is deliberately dumb: one "present" flag and one expected value
    16	 * pointer per possible key. Keys come from a small fixed space so deletes
    17	 * and overwrites actually hit existing keys instead of mostly missing.
    18	 * Because the keys are zero-padded, walking the model by index IS sorted
    19	 * order, which is what rb_foreach must produce.
    20	 *
    21	 * The seed is printed up front and on every failure, so any failure
    22	 * reproduces exactly:  ./build/fuzz <ops> <seed>. */
    23	
    24	enum { KEYSPACE = 512, VALIDATE_EVERY = 100, DEFAULT_SEED = 20260914 };
    25	
    26	static char keys[KEYSPACE][8];              /* "k0000" .. "k0511" */
    27	
    28	struct model {
    29	    bool   present[KEYSPACE];
    30	    int   *value[KEYSPACE];                 /* pointer the tree must hold */
    31	    size_t count;
    32	};
    33	
    34	/* xorshift64*: a few lines of our own so the same seed gives the same op
    35	 * sequence on every machine. rand() differs between libcs, which would make
    36	 * a failure found under valgrind on Linux unreproducible on a Mac. */
    37	static unsigned long long rng_state;
    38	
    39	static unsigned long long rng_next(void)
    40	{
    41	    unsigned long long x = rng_state;
    42	    x ^= x >> 12;
    43	    x ^= x << 25;
    44	    x ^= x >> 27;
    45	    rng_state = x;
    46	    return x * 2685821657736338717ULL;
    47	}
    48	
    49	/* rb_foreach callback: check the tree's in-order sequence against the
    50	 * model's, key and value both. Any missing, extra or misplaced key knocks
    51	 * the two sequences out of step and shows up as a mismatch. */
    52	struct walk {
    53	    const struct model *m;
    54	    int    next;                            /* model index expected next */
    55	    size_t seen;
    56	    long   errors;
    57	    char   first_error[128];
    58	};
    59	
    60	static void walk_cb(const char *key, void *value, void *ctx)
    61	{
    62	    struct walk *w = ctx;
    63	
    64	    /* Invariant: every model key below w->next has been matched already. */
    65	    while (w->next < KEYSPACE && !w->m->present[w->next]) {
    66	        w->next++;
    67	    }
    68	    if (w->next >= KEYSPACE) {
    69	        if (w->errors++ == 0) {
    70	            snprintf(w->first_error, sizeof w->first_error,
    71	                     "tree yielded %s after the model ran out of keys", key);
    72	        }
    73	    } else if (strcmp(key, keys[w->next]) != 0 || value != w->m->value[w->next]) {
    74	        if (w->errors++ == 0) {
    75	            snprintf(w->first_error, sizeof w->first_error,
    76	                     "tree yielded %s (value %p), model expected %s (value %p)",
    77	                     key, value, keys[w->next], (void *)w->m->value[w->next]);
    78	        }
    79	    }
    80	    w->next++;
    81	    w->seen++;
    82	}
    83	
    84	/* Full check: all five rules, the count, and the complete in-order
    85	 * contents. Returns a message on failure, NULL when everything agrees. */
    86	static const char *check_tree(const rbtree_t *t, const struct model *m)
    87	{
    88	    static char msg[256];
    89	
    90	    int rc = rb_validate(t);
    91	    if (rc != 0) {
    92	        snprintf(msg, sizeof msg, "rb_validate returned %d", rc);
    93	        return msg;
    94	    }
    95	    if (rb_size(t) != m->count) {
    96	        snprintf(msg, sizeof msg, "rb_size %zu, model has %zu", rb_size(t), m->count);
    97	        return msg;
    98	    }
    99	
   100	    struct walk w = { .m = m, .next = 0, .seen = 0, .errors = 0, .first_error = "" };
   101	    rb_foreach(t, walk_cb, &w);
   102	    if (w.errors != 0) {
   103	        snprintf(msg, sizeof msg, "foreach: %s", w.first_error);
   104	        return msg;
   105	    }
   106	    if (w.seen != m->count) {
   107	        snprintf(msg, sizeof msg, "foreach visited %zu keys, model has %zu",
   108	                 w.seen, m->count);
   109	        return msg;
   110	    }
   111	    return NULL;
   112	}
