   114	static void die(rbtree_t *t, long op, unsigned long long seed, const char *what,
   115	                const char *detail)
   116	{
   117	    fprintf(stderr, "fuzz: FAIL at op %ld (seed %llu): %s -- %s\n"
   118	                    "      reproduce with: ./build/fuzz %ld %llu\n",
   119	            op, seed, what, detail, op + 1, seed);
   120	    rb_destroy(t);
   121	    exit(1);
   122	}
