   124	int main(int argc, char **argv)
   125	{
   126	    long ops = (argc > 1) ? strtol(argv[1], NULL, 10) : 0;
   127	    unsigned long long seed = (argc > 2) ? strtoull(argv[2], NULL, 10)
   128	                                         : DEFAULT_SEED;
