   139	    static struct model m;                  /* zeroed: nothing present */
   140	    rbtree_t *t = rb_create(free);          /* the tree owns the values */
   141	    if (t == NULL) {
   142	        fprintf(stderr, "fuzz: rb_create failed\n");
   143	        return 1;
   144	    }
   145	
   146	    size_t max_size = 0;
   147	    long validations = 0;
   148	    char what[64];
   149	
   150	    /* Invariant: after every op, the tree and the model agree on which keys
   151	     * are present, which value pointer each maps to, and the count. */
   152	    for (long op = 0; op < ops; op++) {
   153	        unsigned long long r = rng_next();
   154	        int k = (int)(r % KEYSPACE);
   155	        int kind = (int)((r >> 32) % 10);   /* 0-3 insert, 4-6 delete, 7-9 find */
   156	
   157	        if (kind < 4) {
   158	            int *v = malloc(sizeof *v);
   159	            if (v == NULL) {
   160	                die(t, op, seed, "malloc", "out of memory in the fuzzer itself");
   161	            }
   162	            *v = (int)op;
   163	            snprintf(what, sizeof what, "insert %s%s", keys[k],
   164	                     m.present[k] ? " (overwrite)" : "");
