   166	                free(v);                    /* -1: caller still owns it */
   167	                die(t, op, seed, what, "rb_insert returned -1");
   168	            }
   169	            if (!m.present[k]) {
   170	                m.present[k] = true;
   171	                m.count++;
   172	            }
   173	            m.value[k] = v;                 /* overwrite: tree freed the old one */
   174	        } else if (kind < 7) {
   175	            snprintf(what, sizeof what, "delete %s%s", keys[k],
   176	                     m.present[k] ? "" : " (absent)");
   177	            int rc = rb_delete(t, keys[k]);
   178	            int want = m.present[k] ? 0 : -1;
   179	            if (rc != want) {
   180	                char d[64];
   181	                snprintf(d, sizeof d, "rb_delete returned %d, expected %d", rc, want);
   182	                die(t, op, seed, what, d);
   183	            }
   184	            if (m.present[k]) {
   185	                m.present[k] = false;
   186	                m.value[k] = NULL;
   187	                m.count--;
   188	            }
   189	        } else {
   190	            snprintf(what, sizeof what, "find %s%s", keys[k],
   191	                     m.present[k] ? "" : " (absent)");
   192	            void *got = rb_find(t, keys[k]);
   193	            void *want = m.present[k] ? (void *)m.value[k] : NULL;
   194	            if (got != want) {
   195	                char d[64];
   196	                snprintf(d, sizeof d, "rb_find returned %p, expected %p", got, want);
   197	                die(t, op, seed, what, d);
   198	            }
   199	        }
   200	
   201	        if (rb_size(t) != m.count) {
   202	            char d[64];
   203	            snprintf(d, sizeof d, "rb_size %zu, model has %zu", rb_size(t), m.count);
   204	            die(t, op, seed, what, d);
   205	        }
   206	        if (m.count > max_size) {
   207	            max_size = m.count;
   208	        }
   209	
   210	        if ((op + 1) % VALIDATE_EVERY == 0) {
   211	            const char *bad = check_tree(t, &m);
   212	            validations++;
   213	            if (bad != NULL) {
   214	                die(t, op, seed, what, bad);
   215	            }
   216	        }
   217	    }
   218	
   219	    /* One last full check, then tear down and make sure nothing leaked. */
   220	    const char *bad = check_tree(t, &m);
   221	    validations++;
   222	    if (bad != NULL) {
   223	        die(t, ops, seed, "final check", bad);
   224	    }
   225	    size_t final_size = m.count;
   226	    rb_destroy(t);
