   229	                        "rb_destroy\n", seed, rb_debug_live_allocs());
   230	        return 1;
   231	    }
   232	
   233	    printf("fuzz: %ld ops ok, seed %llu, %ld full checks, peak size %zu, "
   234	           "final size %zu, 0 blocks leaked\n",
   235	           ops, seed, validations, max_size, final_size);
   236	    return 0;
   237	}

