    for (int i = 0; i < n; i++) idx[i] = i;
    if (order == 1) for (int i = 0; i < n/2; i++) { int tmp = idx[i]; idx[i] = idx[n-1-i]; idx[n-1-i] = tmp; }
    if (order == 2) for (int i = n-1; i > 0; i--) { int j = (int)(xs() % (unsigned)(i+1)); int tmp = idx[i]; idx[i] = idx[j]; idx[j] = tmp; }
    if (order == 3) { int lo = n/2, hi = n/2+1, k = 0; while (k < n) { if (lo >= 0) idx[k++] = lo--; if (hi < n && k < n) idx[k++] = hi++; } }
    int bad = 0;
    for (int i = 0; i < n; i++) {
        if (rb_delete(t, keys[idx[i]]) != 0) { bad++; break; }
        int v = rb_validate(t);
        if (v != 0) { printf("  %s: validate=%d after %d deletes\n", label, v, i+1); bad++; break; }
        if (rb_size(t) != (size_t)(n - i - 1)) { bad++; break; }
    }
    size_t live_before_destroy = rb_debug_live_allocs();   /* should be 1: just the tree struct */
    rb_destroy(t);
    size_t live = rb_debug_live_allocs();
    printf("PROBE B %-12s n=%d: drained ok=%s, live blocks before destroy=%zu (expect 1), after destroy=%zu  [%s]\n",
           label, n, bad ? "NO" : "yes", live_before_destroy, live,
           (!bad && live_before_destroy == 1 && live == 0) ? "clean" : "PROBLEM");
    free(keys); free(idx);
    return bad || live != 0;
}

/* Partial drains: delete a random half, destroy, check every block came back. */
static int partial_drain_destroy(int n, int rounds)
{
    int problems = 0;
    for (int r = 0; r < rounds; r++) {
        rbtree_t *t = rb_create(free);
        char k[8];
        for (int i = 0; i < n; i++) { snprintf(k, 8, "k%05d", i); int *v = malloc(sizeof *v); *v = i; rb_insert(t, k, v); }
        size_t expect = (size_t)n;
        for (int i = 0; i < n; i++) if (xs() & 1) { snprintf(k, 8, "k%05d", i); if (rb_delete(t, k) == 0) expect--; }
        if (rb_validate(t) != 0 || rb_size(t) != expect) problems++;
        /* the tree struct + (node + key) per survivor */
        size_t want_live = 1 + 2 * expect;
        if (rb_debug_live_allocs() != want_live) { printf("  round %d: live=%zu want=%zu\n", r, rb_debug_live_allocs(), want_live); problems++; }
        rb_destroy(t);
        if (rb_debug_live_allocs() != 0) problems++;
    }
    printf("PROBE B partial-drain+destroy: n=%d x %d rounds, problems=%d  [%s]\n", n, rounds, problems, problems ? "PROBLEM" : "clean");
    return problems;
}

/* ---------- Probe C: NULL arguments, each in a child so a crash is a report ---------- */
static void in_child(const char *label, void (*fn)(void))
{
    fflush(stdout);
    pid_t pid = fork();
    if (pid == 0) { fn(); _exit(0); }
    int st; waitpid(pid, &st, 0);
    if (WIFEXITED(st)) printf("PROBE C %-40s -> returned normally (exit %d)\n", label, WEXITSTATUS(st));
    else if (WIFSIGNALED(st)) printf("PROBE C %-40s -> CRASH: signal %d (%s)\n", label, WTERMSIG(st), strsignal(WTERMSIG(st)));
}
static void c_delete_null_key_empty(void)   { rbtree_t *t = rb_create(NULL); int rc = rb_delete(t, NULL); rb_destroy(t); _exit(rc == -1 ? 0 : 3); }
static void c_delete_null_key_nonempty(void){ rbtree_t *t = rb_create(NULL); rb_insert(t, "a", NULL); rb_delete(t, NULL); rb_destroy(t); }
static void c_delete_null_tree(void)        { rb_delete(NULL, "a"); }
static void c_foreach_null_tree(void)       { rb_foreach(NULL, NULL, NULL); }
static void c_foreach_null_fn_empty(void)   { rbtree_t *t = rb_create(NULL); rb_foreach(t, NULL, NULL); rb_destroy(t); }
static void c_foreach_null_fn_nonempty(void){ rbtree_t *t = rb_create(NULL); rb_insert(t, "a", NULL); rb_foreach(t, NULL, NULL); rb_destroy(t); }
static void c_find_null_key_empty(void)     { rbtree_t *t = rb_create(NULL); rb_find(t, NULL); rb_destroy(t); }
static void c_find_null_key_nonempty(void)  { rbtree_t *t = rb_create(NULL); rb_insert(t, "a", NULL); rb_find(t, NULL); rb_destroy(t); }
static void c_validate_null_tree(void)      { rb_validate(NULL); }
static void c_size_null_tree(void)          { _exit(rb_size(NULL) == 0 ? 0 : 3); }
static void c_destroy_null_tree(void)       { rb_destroy(NULL); }

/* ---------- Probe D: delete during foreach (header says nothing about it) ---------- */
static void deleting_cb(const char *key, void *value, void *ctx)
{
    (void)value;
    rb_delete((rbtree_t *)ctx, key);   /* key is the tree's OWN key pointer */
}
static void d_delete_during_foreach(void)
{
    rbtree_t *t = rb_create(NULL);
    rb_insert(t, "b", NULL); rb_insert(t, "a", NULL); rb_insert(t, "c", NULL);
    rb_foreach(t, deleting_cb, t);     /* a is a red leaf: node freed, then walk reads n->right */
    rb_destroy(t);
}

/* ---------- Probe E: delete using the tree's own key pointer (after the walk) ---------- */
static const char *captured;
static void capture_cb(const char *key, void *value, void *ctx) { (void)value; (void)ctx; if (strcmp(key, "d") == 0) captured = key; }
static void probe_alias_key(void)
{
    rbtree_t *t = rb_create(free);
    const char *ins = "dbfaceg";
    for (const char *p = ins; *p; p++) { char k[2] = { *p, 0 }; int *v = malloc(sizeof *v); *v = *p; rb_insert(t, k, v); }
    rb_foreach(t, capture_cb, NULL);
    int rc = rb_delete(t, captured);   /* d = root, two children: its key pointer is swapped into the successor node and freed */
    printf("PROBE E delete via tree's own key pointer (two-children root): rc=%d validate=%d size=%zu  [%s]\n",
           rc, rb_validate(t), rb_size(t), (rc == 0 && rb_validate(t) == 0 && rb_size(t) == 6) ? "clean" : "PROBLEM");
    rb_destroy(t);
}

int main(void)
{
    puts("== A: what a value_free callback observes ==");
    probe_reentrant_value_free();
    puts("\n== B: large-tree drains and destroy after many deletes ==");
    int b = 0;
    b |= drain("ascending", 4096, 0);
    b |= drain("descending", 4096, 1);
    b |= drain("shuffled", 4096, 2);
    b |= drain("middle-out", 4096, 3);
    b |= drain("shuffled", 100000, 2);
    b |= partial_drain_destroy(2000, 50);
    puts("\n== C: NULL arguments (each in a forked child) ==");
    in_child("rb_size(NULL)",                        c_size_null_tree);
    in_child("rb_destroy(NULL)",                     c_destroy_null_tree);
    in_child("rb_delete(t, NULL) on EMPTY tree",     c_delete_null_key_empty);
    in_child("rb_delete(t, NULL) on NON-EMPTY tree", c_delete_null_key_nonempty);
    in_child("rb_delete(NULL, key)",                 c_delete_null_tree);
    in_child("rb_find(t, NULL) on EMPTY tree",       c_find_null_key_empty);
    in_child("rb_find(t, NULL) on NON-EMPTY tree",   c_find_null_key_nonempty);
    in_child("rb_foreach(NULL, ..)",                 c_foreach_null_tree);
    in_child("rb_foreach(t, fn=NULL) on EMPTY",      c_foreach_null_fn_empty);
    in_child("rb_foreach(t, fn=NULL) on NON-EMPTY",  c_foreach_null_fn_nonempty);
    in_child("rb_validate(NULL)",                    c_validate_null_tree);
    puts("\n== D: rb_delete inside an rb_foreach callback (in a child; ASan report follows if UAF) ==");
    in_child("delete current key during foreach",    d_delete_during_foreach);
    puts("\n== E: key-pointer aliasing ==");
    probe_alias_key();
    return b;
}
